var n=`1097-laap`;var t=`world-1097`;var s=`LA`;var a=`southeast-asia`;var r=4;var o=21;var u={en:`Laap`,ua:`Лаап`};var l={en:`Laap is a dish from Laos prepared with ground pork, fish sauce, lime juice, shallot. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Лаап, страва кухні країни Лаос, яку готують із таких продуктів: свинячий фарш, рибний соус, сік лайма, цибуля шалот. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 9 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 9 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:9,i:[[`ground-pork`,600,`g`],[`sunflower-oil`,20,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`fish-sauce`,40,`ml`],[`lime-juice`,60,`ml`],[`crushed-red-pepper`,5,`g`],[`shallot`,110,`g`]]},{en:`Toast these ingredients over medium heat for about 4 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 4 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:4,i:[[`glutinous-rice`,30,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`mint`,30,`g`],[`cilantro`,20,`g`],[`lettuce`,180,`g`]]}];var d={slug:n,id:t,country:`LA`,region:a,servings:4,minutes:21,title:u,text:l,steps:g};export{s as country,d as default,t as id,o as minutes,a as region,r as servings,n as slug,g as steps,l as text,u as title};